import type { Repository } from "../config/index.js";
import { CommandError, type Runner } from "../runtime/index.js";

const gateCrd = "crd/koreapplicationadmission.constraints.gatekeeper.sh";

/**
 * The parameters the live constraint CRD declares. The CRD is generated by
 * Gatekeeper from the `KoreApplicationAdmission` template, which belongs to
 * kore-policy-templates alone and is updated later in a run than the gate is
 * first closed. A constraint carrying a parameter the live schema does not
 * declare is rejected by the API server, so the gate is written against what
 * the cluster declares now (ADR 0067). Undefined when the CRD does not exist.
 */
export async function declaredGateParameters(
  repository: Repository,
  runner: Runner,
): Promise<Set<string> | undefined> {
  let stdout: string;
  try {
    ({ stdout } = await runner.run(
      "kubectl",
      [
        "--context",
        repository.environment.kubeContext,
        "get",
        gateCrd,
        "--ignore-not-found",
        "--output",
        "json",
      ],
      { capture: true },
    ));
  } catch (error) {
    if (
      error instanceof CommandError &&
      /NotFound|not found/.test(error.result.stderr)
    ) {
      return undefined;
    }
    throw error;
  }
  if (stdout.trim() === "") {
    return undefined;
  }
  const versions =
    (
      JSON.parse(stdout) as {
        spec?: {
          versions?: {
            name?: string;
            schema?: {
              openAPIV3Schema?: {
                properties?: {
                  spec?: {
                    properties?: {
                      parameters?: { properties?: Record<string, unknown> };
                    };
                  };
                };
              };
            };
          }[];
        };
      }
    ).spec?.versions ?? [];
  const version = versions.find(({ name }) => name === "v1beta1");
  return new Set(
    Object.keys(
      version?.schema?.openAPIV3Schema?.properties?.spec?.properties?.parameters
        ?.properties ?? {},
    ),
  );
}
